std::vector<SersicMixValues> get_sersic_mix_knots_copy(unsigned short order, const std::string& version) {
    const auto version_map = KNOT_DEFINITIONS.find(order);
    if (version_map == KNOT_DEFINITIONS.end()) {
        throw std::invalid_argument("Unimplemented Sersic mixture order=" + std::to_string(order));
    }
    const auto knots = version_map->second.find(version);
    if (knots == version_map->second.end()) {
        throw std::invalid_argument("Unknown Sersic mixture version=" + version
                                    + " for order=" + std::to_string(order));
    }
    return knots->second.second;
};

